private object Kizuna {
    fun resolveUrl(baseUrl: String, path: String): HttpUrl.Builder {
        val base = baseUrl.toHttpUrl()
        val trimmedPath = path.trimStart('/')
        val basePath = base.encodedPath.trimEnd('/')
        val fullPath = if (basePath.isEmpty()) "/$trimmedPath" else "$basePath/$trimmedPath"
        return base.newBuilder().encodedPath(fullPath)
    }

    fun encodePathSegment(value: Any): String {
        val text = stringifyQueryValue(value).firstOrNull() ?: ""
        return java.net.URLEncoder.encode(text, "UTF-8").replace("+", "%20")
    }

    fun stringifyQueryValue(value: Any): List<String> {
        return when (value) {
            is Instant -> listOf(value.toString())
            is List<*> -> value.filterNotNull().flatMap { stringifyQueryValue(it) }
            is KizunaQueryValue -> listOf(value.wireValue)
            is Enum<*> -> listOf(value.name)
            else -> listOf(value.toString())
        }
    }

    suspend fun execute(client: OkHttpClient, request: Request): Response {
        return kotlinx.coroutines.suspendCancellableCoroutine { continuation ->
            val call = client.newCall(request)
            continuation.invokeOnCancellation {
                call.cancel()
            }
            call.enqueue(object : Callback {
                override fun onFailure(call: Call, e: java.io.IOException) {
                    continuation.resumeWith(Result.failure(e))
                }
                override fun onResponse(call: Call, response: Response) {
                    continuation.resumeWith(Result.success(response))
                }
            }
            )
        }
    }
}
